"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Cualquier sala: visión en expedición +{0}, multiplicador de puntos inicial +{1}. Afín a «Fortuna / Especial»: el mapa de la expedición empieza totalmente revelado, multiplicador +{2} más.",
