"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Cualquier sala: vida de las tropas en expedición +{0}%. Afín a «Medicina»: curación del hospital +{1}%, el líder recupera un {2}% más al día.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Cualquier sala: probabilidad de planos +{0}%. Afín a «Ciencia ficción»: base +{1} Fragmentos de alma al día.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Cualquier sala: probabilidad de planos +{0}%. Afín a «Forja»: {1}% de probabilidad de una reliquia extra al forjar.",
