"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Cualquier sala: base +{0} suministros al día, el líder gana {1} EXP al día. Afín a «Logística / Naturaleza»: efecto propio de esta sala ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Cualquier sala: coste de forja de reliquias -{0}%. Afín a «Forja / Arma»: al forjar, {1}% de probabilidad de calidad +{2}; las armas hacen +{3}% de daño.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Cualquier sala: tiempo de obra a la mitad; al terminar se devuelve un {0}% de los suministros. Afín a «Maravilla»: la devolución sube al {1}%.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Cualquier sala: todas las torres defensivas hacen +{0}% de daño. Afín a «Arma»: alcance +{1}, vel. de ataque +{2}%.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Cualquier sala: coste de excavación -{0}%. Afín a «Especial»: todas las obras tardan {1} d. menos.",
